#!ibl edition=2
$D = "guestpc-7a440e9daf61"
$R = "/tmp"
$kid = "python3 -c 'import time;time.sleep(120)'"
# (1) 한도 2 에 셋을 한꺼번에
$q1 = [limbs:guestpc]{op:"shell",limb:$D,cmd:"sleep 6; echo one",cwd:$R,background:true,request_id:"r50-probe-q1-b"}
$q2 = [limbs:guestpc]{op:"shell",limb:$D,cmd:"sleep 6; echo two",cwd:$R,background:true,request_id:"r50-probe-q2-b"}
$q3 = [limbs:guestpc]{op:"shell",limb:$D,cmd:"sleep 6; echo three",cwd:$R,background:true,request_id:"r50-probe-q3-b"}
$w0 = [self:task]{op:"wait",ref:$q1.task_ref,timeout:2}
$s3 = [self:task]{op:"status",ref:$q3.task_ref}
# (2) 취소: 자식 2개 + 루프
$c = [limbs:guestpc]{op:"shell",limb:$D,cmd:f"${kid} R50=probe-c-1 & ${kid} R50=probe-c-2 & while :; do echo tick; sleep 2; done",cwd:$R,background:true,request_id:"r50-probe-cancel-b"}
$wq = [self:task]{op:"wait",ref:$q3.task_ref,timeout:25}
$cw = [self:task]{op:"wait",ref:$c.task_ref,timeout:3}
$stop = [fn:외부PC작업중지확인]{작업:{**$c,op:"shell"},대기:20}
$ps1 = [limbs:guestpc]{op:"shell",limb:$D,cmd:"ps -axo pid,ppid,etime,command | grep 'R50[=]probe-c' | cut -c1-120; true",cwd:$R,request_id:"r50-probe-ps1-b"}
# (3) 제한시간 5초
$t = [limbs:guestpc]{op:"shell",limb:$D,cmd:f"${kid} R50=probe-t-1 & echo holding; sleep 60; echo never",cwd:$R,background:true,timeout:5,request_id:"r50-probe-limit-b"}
$tc = [fn:외부PC작업확인]{작업:{**$t,op:"shell"},대기:25}
$ps2 = [limbs:guestpc]{op:"shell",limb:$D,cmd:"ps -axo pid,ppid,etime,command | grep 'R50[=]probe-t' | cut -c1-120; true",cwd:$R,request_id:"r50-probe-ps2-b"}
# (4) 끝난 뒤에도 사는 자식: 출력 통로를 닫은 것 / 안 닫은 것
$n1 = [limbs:guestpc]{op:"shell",limb:$D,cmd:f"nohup ${kid} R50=probe-n-closed > /dev/null 2>&1 < /dev/null & sleep 1; echo started",cwd:$R,background:true,timeout:30,request_id:"r50-probe-nohup1-b"}
$n1c = [fn:외부PC작업확인]{작업:{**$n1,op:"shell"},대기:25}
$n2 = [limbs:guestpc]{op:"shell",limb:$D,cmd:f"nohup ${kid} R50=probe-n-open & sleep 1; echo started",cwd:$R,background:true,timeout:30,request_id:"r50-probe-nohup2-b"}
$n2c = [fn:외부PC작업확인]{작업:{**$n2,op:"shell"},대기:40}
$ps3 = [limbs:guestpc]{op:"shell",limb:$D,cmd:"ps -axo pid,ppid,etime,command | grep 'R50[=]probe-n' | cut -c1-120; pkill -f 'R50[=]probe-'; sleep 1; echo AFTER; ps -axo pid,command | grep 'R50[=]probe-' | wc -l",cwd:$R,request_id:"r50-probe-ps3-b"}
$h = [limbs:guestpc]{op:"history",limb:$D}
$mine = map(filter($h.tasks, ($x)=>contains($x.request_id,"r50-probe-") and contains($x.request_id,"-b")), ($x)=>{rid:$x.request_id, state:$x.state, created:$x.created, started:get($x,"started_at",null), ended:get($x,"ended_at",null), seconds:get($x,"seconds",null), result:$x.result})
$slim = ($o)=>{status:$o.status, settled:$o.settled, command_ok:$o.command_ok, exit:$o.exit, seconds:$o.seconds, result:$o.result, failure:$o.failure, scope:$o.progress_scope}
return {q3_at_2s:{state:$s3.state}, cancel:{before:$cw.state, stopped:$stop.stopped, status:$stop.status, settled:$stop.settled, result:$stop.result, seconds:$stop.seconds, cancel_obs:get($stop,"cancel_observation",null)}, ps_after_cancel:$ps1.result.output,
  limit:$slim($tc), ps_after_limit:$ps2.result.output, nohup_closed:$slim($n1c), nohup_open:$slim($n2c), ps_nohup:$ps3.result.output, ledger:$mine}
